using System.IO.Compression;
using System.Net;
using System.Security.Cryptography;
using Vemo.Provision;
using Xunit;
namespace Vemo.Provision.Tests;
public sealed class DownloadTests : IDisposable {
    readonly string root=Path.Combine(OperatingSystem.IsMacOS()?"/private/tmp":Path.GetTempPath(),"vemo-download-"+Guid.NewGuid());
    public DownloadTests()=>Directory.CreateDirectory(root);
    public void Dispose()=>Directory.Delete(root,true);
    static DownloadPin Pin(byte[] bytes)=>new("model.bin","https://huggingface.co/owner/repo/resolve/pin/model.bin",bytes.Length,Convert.ToHexStringLower(SHA256.HashData(bytes)));
    [Fact] public async Task DownloadVerifiedThenOfflineReuse(){byte[] bytes=[1,2,3];var calls=0;using var http=new HttpClient(new Handler(request=>{calls++;return new(HttpStatusCode.OK){Content=new ByteArrayContent(bytes),RequestMessage=request};}));var downloads=new PinnedDownloads(http);var path=await downloads.AcquireAsync(Pin(bytes),root,false,default);Assert.Equal(bytes,File.ReadAllBytes(path));Assert.Equal(path,await downloads.AcquireAsync(Pin(bytes),root,true,default));Assert.Equal(1,calls);Assert.Empty(Directory.GetFiles(root,"*.partial-*"));}
    [Fact] public async Task BadHashCleansPartialAndPreservesExisting(){byte[] expected=[1,2,3];using var http=new HttpClient(new Handler(request=>new(HttpStatusCode.OK){Content=new ByteArrayContent([3,2,1]),RequestMessage=request}));var downloads=new PinnedDownloads(http);await Assert.ThrowsAsync<InvalidDataException>(()=>downloads.AcquireAsync(Pin(expected),root,false,default));Assert.Empty(Directory.GetFiles(root));var path=Path.Combine(root,"model.bin");File.WriteAllBytes(path,[9,9,9]);await Assert.ThrowsAsync<InvalidDataException>(()=>downloads.AcquireAsync(Pin(expected),root,false,default));Assert.Equal(new byte[]{9,9,9},File.ReadAllBytes(path));}
    [Fact] public async Task OfflineMissingAndOversizeNeverPublish(){byte[] expected=[1,2,3];using var http=new HttpClient(new Handler(request=>new(HttpStatusCode.OK){Content=new ByteArrayContent([1,2,3,4]),RequestMessage=request}));var downloads=new PinnedDownloads(http);await Assert.ThrowsAsync<FileNotFoundException>(()=>downloads.AcquireAsync(Pin(expected),root,true,default));await Assert.ThrowsAsync<InvalidDataException>(()=>downloads.AcquireAsync(Pin(expected),root,false,default));Assert.Empty(Directory.GetFiles(root));}
    [Theory][InlineData("../escape.exe")][InlineData("C:/escape.exe")][InlineData("dir/../../escape.exe")][InlineData("dir\\..\\escape.exe")][InlineData("CON.exe")]
    public void ZipTraversalRejectedAndStagingCleaned(string name){var zip=Path.Combine(root,"test.zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create)){using var w=new StreamWriter(z.CreateEntry(name).Open());w.Write("bad");}Assert.ThrowsAny<Exception>(()=>PinnedDownloads.Extract(zip,Path.Combine(root,"runtime")));Assert.False(Directory.Exists(Path.Combine(root,"runtime")));Assert.Empty(Directory.GetDirectories(root));}
    [Fact] public void ValidZipPreservesDependencyTreeAndRejectsOverwrite(){var zip=Path.Combine(root,"test.zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create)){using var w=new StreamWriter(z.CreateEntry("Release/whisper-cli.exe").Open());w.Write("fixture");}var target=Path.Combine(root,"runtime");PinnedDownloads.Extract(zip,target);Assert.Equal("fixture",File.ReadAllText(Path.Combine(target,"Release","whisper-cli.exe")));Assert.Throws<IOException>(()=>PinnedDownloads.Extract(zip,target));}
    [Fact] public async Task CancellationCleansPartial(){byte[] bytes=[1,2,3];using var cts=new CancellationTokenSource();using var http=new HttpClient(new Handler(request=>{cts.Cancel();return new(HttpStatusCode.OK){Content=new ByteArrayContent(bytes),RequestMessage=request};}));await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>new PinnedDownloads(http).AcquireAsync(Pin(bytes),root,false,cts.Token));Assert.Empty(Directory.GetFiles(root));}
    [Fact] public void ZipSymlinksRejected(){var zip=Path.Combine(root,"link.zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create)){var entry=z.CreateEntry("link");entry.ExternalAttributes=unchecked((int)(0xa1ffU<<16));using var w=new StreamWriter(entry.Open());w.Write("elsewhere");}Assert.ThrowsAny<Exception>(()=>PinnedDownloads.Extract(zip,Path.Combine(root,"runtime")));Assert.Empty(Directory.GetDirectories(root));}
    [Fact] public void RejectUntrustedPins(){Assert.ThrowsAny<Exception>(()=>new DownloadPin("../bad","https://huggingface.co/file",1,new string('a',64)).Validate());Assert.ThrowsAny<Exception>(()=>new DownloadPin("model.bin","http://huggingface.co/file",1,new string('a',64)).Validate());Assert.ThrowsAny<Exception>(()=>new DownloadPin("model.bin","https://example.org/file",1,new string('a',64)).Validate());}
    sealed class Handler(Func<HttpRequestMessage,HttpResponseMessage> respond):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct)=>Task.FromResult(respond(request));}
}
